let raw;try{raw=localStorage.getItem('meu-ritmo-lite:v1');if(raw)document.querySelector('#old-data').hidden=false}catch{}document.querySelector('#export').addEventListener('click',()=>{try{const value=localStorage.getItem('meu-ritmo-lite:v1');if(!value)throw Error();JSON.parse(value);const url=URL.createObjectURL(new Blob([value],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='meu-ritmo-lite-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#export-status').textContent='Arquivo preparado. Confira seus downloads antes de apagar qualquer dado.'}catch{document.querySelector('#export-status').textContent='Não foi possível exportar. Seus dados não foram apagados.'}});fetch('release.json').then(r=>r.json()).then(r=>{document.querySelector('#version').textContent=`Versão ${r.version} · Android ${r.minAndroid} ou superior · ${(r.size/1048576).toFixed(1).replace('.',',')} MB`;document.querySelector('#checksum').textContent='SHA-256: '+r.sha256}).catch(()=>{});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});